begin;
create or replace function allocate_spin(p_campaign text,p_name text,p_phone text,p_request_id uuid) returns table(spin_id uuid,prize_code text,prize_name text,sector int,turn_left int) language plpgsql security definer set search_path=public as $$declare c campaigns;part participants;u prize_units;s spins;canonical_phone text;updated_units int;begin canonical_phone:=case when p_phone~'^\+84[35789][0-9]{8}$'then'0'||substring(p_phone from 4)when p_phone~'^\+81[0-9]{9,10}$'then'0'||substring(p_phone from 4)else p_phone end;select * into c from campaigns where code=p_campaign and status='ACTIVE' and(starts_at is null or starts_at<=now())and(ends_at is null or ends_at>=now())for update;if not found then raise exception 'CAMPAIGN_INACTIVE';end if;select sp.* into s from spins sp where sp.request_id=p_request_id;if found then if s.campaign_id<>c.id then raise exception 'REQUEST_ID_CONFLICT';end if;return query select s.id,p.code,p.name,p.wheel_index,0 from prizes p where p.id=s.prize_id;return;end if;insert into participants(campaign_id,name,phone,phone_normalized)values(c.id,trim(p_name),canonical_phone,regexp_replace(canonical_phone,'\D','','g'))on conflict(campaign_id,phone_normalized)do update set name=excluded.name returning * into part;if exists(select 1 from spins where campaign_id=c.id and participant_id=part.id)then raise exception 'ALREADY_SPUN';end if;select pu.* into u from prize_units pu join prizes p on p.id=pu.prize_id and p.campaign_id=c.id and p.active where pu.campaign_id=c.id and pu.status='AVAILABLE' order by random() for update of pu skip locked limit 1;if not found then raise exception 'CAMPAIGN_SOLD_OUT';end if;insert into spins(campaign_id,participant_id,prize_id,prize_unit_id,request_id,status,claimed_at,sheet_sync_status)values(c.id,part.id,u.prize_id,u.id,p_request_id,'CLAIMED',now(),'PENDING')returning * into s;update prize_units set status='CLAIMED',awarded_at=now(),participant_id=part.id,spin_id=s.id where id=u.id and status='AVAILABLE';get diagnostics updated_units=row_count;if updated_units<>1 then raise exception 'PRIZE_UNIT_STATE_CONFLICT';end if;return query select s.id,p.code,p.name,p.wheel_index,0 from prizes p where p.id=u.prize_id;end$$;
revoke all on function allocate_spin(text,text,text,uuid) from public,anon,authenticated;
grant execute on function allocate_spin(text,text,text,uuid) to service_role;
create or replace function admin_audit_campaign_invariants(p_campaign text) returns jsonb language sql security definer set search_path=public as $$with c as(select id,total_inventory,inventory_version from campaigns where code=p_campaign),counts as(select count(*)::int unit_count,count(*)filter(where pu.status='AVAILABLE')::int available,count(*)filter(where pu.status='AWARDED')::int awarded,count(*)filter(where pu.status='CLAIMED')::int claimed from prize_units pu join c on c.id=pu.campaign_id),checks as(select count(*)filter(where pu.id is null or pu.spin_id is distinct from s.id or pu.participant_id is distinct from s.participant_id or pu.prize_id is distinct from s.prize_id or pu.status is distinct from s.status)::int broken_spin_unit_links,count(*)filter(where s.status not in('AWARDED','CLAIMED'))::int invalid_spin_statuses from spins s join c on c.id=s.campaign_id left join prize_units pu on pu.id=s.prize_unit_id),orphans as(select count(*)filter(where pu.status='AVAILABLE'and(pu.spin_id is not null or pu.participant_id is not null))::int dirty_available_units,count(*)filter(where pu.status in('AWARDED','CLAIMED')and(pu.spin_id is null or pu.participant_id is null))::int detached_allocated_units from prize_units pu join c on c.id=pu.campaign_id),catalog as(select count(*)::int prize_types,count(distinct wheel_index)::int unique_sectors,coalesce(sum(total_qty),0)::int configured_total from prizes p join c on c.id=p.campaign_id where p.active)select jsonb_build_object('ok',(select broken_spin_unit_links=0 and invalid_spin_statuses=0 from checks)and(select dirty_available_units=0 and detached_allocated_units=0 from orphans)and(select unit_count=(select total_inventory from c)from counts)and(select prize_types=unique_sectors from catalog),'campaign',(select to_jsonb(c)from c),'inventory',(select to_jsonb(counts)from counts),'links',(select to_jsonb(checks)from checks),'orphans',(select to_jsonb(orphans)from orphans),'catalog',(select to_jsonb(catalog)from catalog));$$;
revoke all on function admin_audit_campaign_invariants(text) from public,anon,authenticated;
grant execute on function admin_audit_campaign_invariants(text) to service_role;
commit;
